import './PartOne.css';

// 💡 Practical 02 එකේ කියපු විදිහට හදපු පලවෙනිම component එක
export default function PartOne() {
  return (
    <div className="part-one">
      <h3>Hello React!</h3>
      <p>This is my very first custom React component, created as part of Practical 02.</p>
    </div>
  );
}
